Showing configuration parameters with:
  attributes_level = 0
  expert_level = 0

output {
  experiments = 'integrated.expt'
  reflections = 'integrated.refl'
  phil = 'dials.integrate.phil'
  log = 'dials.integrate.log'
  report = None
  include_bad_reference = False
}
scan_range = None
create_profile_model = True
integration {
  lookup {
    mask = None
  }
  block {
    size = auto
    units = *degrees radians frames
    threshold = 0.95
    force = False
    max_memory_usage = 0.80
  }
  use_dynamic_mask = True
  debug {
    reference {
      filename = "reference_profiles.refl"
      output = False
    }
    during = modelling *integration
    output = False
    separate_files = True
    delete_shoeboxes = False
    select = None
    split_experiments = True
  }
  profile {
    fitting = True
    validation {
      number_of_partitions = 1
      min_partition_size = 100
    }
  }
  overlaps_filter {
    foreground_foreground {
      enable = False
    }
    foreground_background {
      enable = False
    }
  }
  mp {
    method = *multiprocessing drmaa sge lsf pbs
    njobs = 1
    nproc = Auto
    multiprocessing.n_subset_split = None
  }
  summation {
    detector_gain = 1
  }
  background {
    algorithm = *Auto glm gmodel null simple
    glm {
      robust {
        tuning_constant = 1.345
      }
      model {
        algorithm = constant2d *constant3d loglinear2d loglinear3d
      }
      min_pixels = 10
    }
    gmodel {
      robust {
        algorithm = False
        tuning_constant = 1.345
      }
      min_pixels = 10
      model = None
    }
    simple {
      outlier {
        algorithm = *null nsigma truncated normal plane tukey
      }
      model {
        algorithm = constant2d *constant3d linear2d linear3d
      }
      min_pixels = 10
    }
  }
  centroid {
    algorithm = *simple
  }
}
profile {
  algorithm = ellipsoid *gaussian_rs
  ellipsoid {
    rlp_mosaicity {
      model = simple1 *simple6 simple1angular1 simple1angular3 \
              simple6angular1
    }
    wavelength_spread {
      model = *delta
    }
    unit_cell {
      fixed = False
    }
    orientation {
      fixed = False
    }
    indexing {
      fail_on_bad_index = False
    }
    refinement {
      max_separation = 2
      outlier_probability = 0.975
      n_macro_cycles = 3
      n_cycles = 3
      min_n_reflections = 10
      max_iter = 100
      LL_tolerance = 1e-3
      mosaicity_max_limit = 0.004
      max_cell_volume_change_fraction = 0.2
    }
  }
  gaussian_rs {
    scan_varying = False
    min_spots {
      overall = 50
      per_degree = 20
    }
    sigma_m_algorithm = basic *extended
    centroid_definition = com *s1
    parameters {
      n_sigma = 3.0
      sigma_b = None
      sigma_m = None
    }
    filter {
      min_zeta = 0.05
    }
    fitting {
      scan_step = 5
      grid_size = 5
      threshold = 0.02
      grid_method = single *regular_grid circular_grid spherical_grid
      fit_method = *reciprocal_space detector_space
      detector_space {
        deconvolution = False
      }
    }
  }
}
prediction {
  d_min = None
  d_max = None
  margin = 1
  force_static = False
  padding = 1.0
}
absorption_correction {
  apply = False
  algorithm = fuller_kapton kapton_2019 other
  fuller_kapton {
    xtal_height_above_kapton_mm {
      value = 0.02
      sigma = 0.01
    }
    rotation_angle_deg {
      value = 1.15
      sigma = 0.1
    }
    kapton_half_width_mm {
      value = 1.5875
      sigma = 0.5
    }
    kapton_thickness_mm {
      value = 0.05
      sigma = 0.005
    }
    smart_sigmas = False
    within_spot_sigmas = True
  }
}
input {
  experiments = None
  reflections = None
}

